 "content": "from collections import deque


def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 4 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            result.append((color, cells))
    return result


def transform(grid):
    out = [row[:] for row in grid]
    comps = components(grid)
    guides = [(color, cells) for color, cells in comps if color == 9]
    if not guides:
        return out
    guide_color, guide = max(guides, key=lambda item: len(item[1]))
    candidates = [(color, cells) for color, cells in comps if color != guide_color]
    if not candidates:
        return out
    def distance(cells):
        return min(abs(y-gy) + abs(x-gx) for y,x in cells for gy,gx in guide)
    color, cells = min(candidates, key=lambda item: (distance(item[1]), -len(item[1])))
    for y, x in cells:
        out[y][x] = guide_color
    return out


if __name__ == '__main__':
    pass
